import { test, expect } from '@playwright/test';

test.describe('Search Filter by Category', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should display search results for selected category', async ({ page }) => {
    await page.getByRole('checkbox', { name: 'Electronics' }).check();
    await page.getByRole('button', { name: 'Search' }).click();

    const results = await page.getByRole('heading', { name: /results/i });
    await expect(results).toBeVisible();

    const firstResult = await page.getByText('Smartphone Model XYZ');
    await expect(firstResult).toBeVisible();
  });

  test('should not display results for unselected category', async ({ page }) => {
    await page.getByRole('checkbox', { name: 'Clothing' }).check();
    await page.getByRole('button', { name: 'Search' }).click();

    const noResultsMessage = await page.getByText('No results found');
    await expect(noResultsMessage).toBeVisible();
  });
});
